<#
.SYNOPSIS
    Restore Kit Research - Agents Individual Item Kits (Icarus). Made by AgentKush.

.DESCRIPTION
    Why this tool exists:
    Workshop research is saved account-wide in Profile.json as a list of talent
    row names. The kit research IDs of "Agents Individual Item Kits" were renamed
    twice: during v1.0 (Agent_Single_X became Workshop_Agent_Single_X) and in v4.0
    (everything became Talent_Agent_Single_X). The game keeps the old names in
    Profile.json but no longer recognises them, so kits you researched on an older
    version stopped showing as researched.

    This tool renames those old entries to the current names. It only edits
    entries inside the top-level "Talents" array of Profile.json and leaves every
    other byte of the file as it was. If the current name is already present
    (you researched the kit again), the old duplicate entry is removed instead.

    Research for kits that were retired from the mod cannot be restored. Those
    entries are listed but never changed.

    Safety:
    - Refuses to change anything while Icarus is running (exit code 2).
    - Checks the edited file with ConvertFrom-Json before writing it.
    - Saves a backup "Profile.json.kitrestore_<yyyyMMdd_HHmmss>.bak" next to the
      profile before writing, and never overwrites an existing file.
    - Running it again when nothing needs changing writes nothing.

.PARAMETER PlayerDataPath
    A PlayerData folder that contains SteamID folders, or a single SteamID folder
    that contains Profile.json. Default:
    %LOCALAPPDATA%\Icarus\Saved\PlayerData

.PARAMETER ProfilePath
    One specific Profile.json file (for dedicated servers or custom locations).

.PARAMETER DryRun
    Report exactly what would change. Writes nothing and creates no backup.

.PARAMETER SkipGameCheck
    For automated testing only. Skips the "is Icarus running" check. Do not use
    this on a real profile while the game is open: the game can overwrite the
    file and undo the restore.

.PARAMETER NoPause
    Used by Restore_Kit_Research.bat to skip its "Press any key" pause. Has no
    effect on the script itself.

.PARAMETER Help
    Show this help.

.EXAMPLE
    .\Restore_Kit_Research.ps1 -DryRun
.EXAMPLE
    .\Restore_Kit_Research.ps1
.EXAMPLE
    .\Restore_Kit_Research.ps1 -ProfilePath "D:\Icarus Server\Saved\PlayerData\76561190000000000\Profile.json"

.NOTES
    Made by AgentKush.
    Exit codes: 0 = success or nothing to do, 1 = a validation or file error,
    2 = Icarus is running.
    Close the game before running. Steam Cloud uploads the updated file the next
    time the game syncs.
#>
#Requires -Version 5.1
[CmdletBinding()]
param(
    [string[]]$PlayerDataPath,
    [string[]]$ProfilePath,
    [switch]$DryRun,
    [switch]$SkipGameCheck,
    [switch]$NoPause,
    [switch]$Help
)

$ErrorActionPreference = 'Stop'

if ($Help) {
    Get-Help -Full $MyInvocation.MyCommand.Path
    exit 0
}

# ---------------------------------------------------------------------------
# Embedded data
# ---------------------------------------------------------------------------

# Old talent row name -> current (v5.3) talent row name. One pair per line.
