# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

function Split-DataLines([string]$data) {
    $out = New-Object System.Collections.Generic.List[string]
    foreach ($line in ($data -split "`r?`n")) {
        $t = $line.Trim()
        if ($t.Length -gt 0) { $out.Add($t) }
    }
    return ,$out
}

$Mapping = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
foreach ($line in (Split-DataLines $MappingData)) {
    $parts = $line -split '\s+'
    if ($parts.Count -ne 2) { throw "Internal error: bad mapping line '$line'" }
    if ($Mapping.ContainsKey($parts[0])) { throw "Internal error: duplicate mapping for '$($parts[0])'" }
    $Mapping.Add($parts[0], $parts[1])
}

$Retired = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
foreach ($line in (Split-DataLines $RetiredData)) { [void]$Retired.Add($line) }

$Unresolved = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
foreach ($line in (Split-DataLines $UnresolvedData)) {
    $m = [regex]::Match($line, '^([A-Za-z0-9_]+) -> ')
    if ($m.Success) { $Unresolved[$m.Groups[1].Value] = $line }
}

$Utf8Strict = New-Object System.Text.UTF8Encoding($false, $true)

function Get-JsonStringEnd([string]$t, [int]$q) {
    # $q is the index of an opening quote. Returns the index of the closing quote.
    $j = $q + 1
    while ($true) {
        $k = $t.IndexOf([char]34, $j)
        if ($k -lt 0) { return -1 }
        $b = 0
        $p = $k - 1
        while ($p -gt $q -and $t[$p] -eq [char]92) { $b++; $p-- }
        if (($b % 2) -eq 0) { return $k }
        $j = $k + 1
    }
}

function Test-JsonWs([char]$c) {
    return ($c -eq [char]32 -or $c -eq [char]9 -or $c -eq [char]13 -or $c -eq [char]10)
}

function Find-TalentsArray([string]$t) {
    # Finds the "[" of the top-level "Talents" array, its matching "]" and the
    # text span of every element. Throws if the structure is not as expected.
    $n = $t.Length
    $depth = 0
    $i = 0
    $opens = New-Object System.Collections.Generic.List[int]
    while ($i -lt $n) {
        $c = $t[$i]
        if ($c -eq [char]34) {
            $e = Get-JsonStringEnd $t $i
            if ($e -lt 0) { throw 'unterminated string in JSON' }
            if ($depth -eq 1) {
                $k = $e + 1
                while ($k -lt $n -and (Test-JsonWs $t[$k])) { $k++ }
                if ($k -lt $n -and $t[$k] -eq ':' -and $t.Substring($i + 1, $e - $i - 1) -ceq 'Talents') {
                    $v = $k + 1
                    while ($v -lt $n -and (Test-JsonWs $t[$v])) { $v++ }
                    if ($v -ge $n -or $t[$v] -ne '[') { throw 'top-level "Talents" is not an array' }
                    $opens.Add($v)
                }
            }
            $i = $e + 1
            continue
        }
        if ($c -eq '{' -or $c -eq '[') { $depth++ }
        elseif ($c -eq '}' -or $c -eq ']') {
            $depth--
            if ($depth -lt 0) { throw 'unbalanced brackets in JSON' }
        }
        $i++
    }
    if ($opens.Count -eq 0) { throw 'no top-level "Talents" array found' }
    if ($opens.Count -gt 1) { throw 'more than one top-level "Talents" key found' }

    $open = $opens[0]
    $starts = New-Object System.Collections.Generic.List[int]
    $ends = New-Object System.Collections.Generic.List[int]
    $i = $open + 1
    $d = 0
    $elStart = -1
    $lastNonWs = -1
    $afterComma = $false
    while ($i -lt $n) {
        $c = $t[$i]
        if ($c -eq [char]34) {
            if ($d -eq 0 -and $elStart -lt 0) { $elStart = $i }
            $e = Get-JsonStringEnd $t $i
            if ($e -lt 0) { throw 'unterminated string in Talents' }
            $lastNonWs = $e
            $i = $e + 1
            continue
        }
        if ($d -eq 0 -and $c -eq ']') {
            if ($elStart -ge 0) {
                $starts.Add($elStart); $ends.Add($lastNonWs + 1)
            }
            elseif ($afterComma) { throw 'trailing comma in Talents' }
            return New-Object PSObject -Property @{ Open = $open; Close = $i; Starts = $starts; Ends = $ends }
        }
        if ($d -eq 0 -and $c -eq ',') {
            if ($elStart -lt 0) { throw 'empty element in Talents' }
            $starts.Add($elStart); $ends.Add($lastNonWs + 1)
            $elStart = -1
            $afterComma = $true
            $i++
            continue
        }
        if (-not (Test-JsonWs $c)) {
            if ($d -eq 0 -and $elStart -lt 0) { $elStart = $i }
            $lastNonWs = $i
        }
        if ($c -eq '{' -or $c -eq '[') { $d++ }
        elseif ($c -eq '}' -or $c -eq ']') { $d-- }
        $i++
    }
    throw 'Talents array is not closed'
}

$EntryRegex = New-Object System.Text.RegularExpressions.Regex (
    '\A\{\s*(?:"RowName"\s*:\s*"(?<n1>[^"\\]*)"\s*,\s*"Rank"\s*:\s*-?[0-9]+(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?\s*' +
    '|"Rank"\s*:\s*-?[0-9]+(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?\s*,\s*"RowName"\s*:\s*"(?<n2>[^"\\]*)"\s*)\}\z')

function Get-EntryNameGroup([string]$elementText) {
    $m = $EntryRegex.Match($elementText)
    if (-not $m.Success) { return $null }
    if ($m.Groups['n1'].Success) { return $m.Groups['n1'] }
    return $m.Groups['n2']
}

function Get-RowName($entry) {
    if ($null -eq $entry) { return $null }
    $p = $entry.PSObject.Properties['RowName']
    if ($null -eq $p -or -not ($p.Value -is [string])) { return $null }
    return [string]$p.Value
}

function Get-ValueSig($v) {
    if ($null -eq $v) { return 'null' }
    if ($v -is [string]) { return 's:' + $v }
    if ($v -is [bool]) { return 'b:' + $v.ToString() }
    if ($v -is [System.ValueType]) { return 'n:' + [string]::Format([System.Globalization.CultureInfo]::InvariantCulture, '{0}', $v) }
    return 'j:' + (ConvertTo-Json -InputObject $v -Depth 20 -Compress)
}

function Get-EntrySig($entry, $nameOverride) {
    # $nameOverride is left untyped on purpose: a [string] parameter turns $null into ''.
    if ($null -eq $entry) { return 'null' }
    if (-not ($entry -is [System.Management.Automation.PSCustomObject])) { return Get-ValueSig $entry }
    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($p in $entry.PSObject.Properties) {
        if ($p.Name -ceq 'RowName' -and $null -ne $nameOverride) {
            $parts.Add('RowName=s:' + $nameOverride)
        }
        else {
            $parts.Add($p.Name + '=' + (Get-ValueSig $p.Value))
        }
    }
    return ($parts -join '|')
}

function Get-TalentList($obj) {
    $p = $obj.PSObject.Properties['Talents']
    if ($null -eq $p) { throw 'parsed JSON has no Talents property' }
    return ,@($p.Value)
}

function ConvertTo-B64([byte[]]$b) { return [System.Convert]::ToBase64String($b) }

function Get-SteamIdLabel([string]$file) {
    return (Split-Path -Leaf (Split-Path -Parent $file))
}

# ---------------------------------------------------------------------------
# One profile
# ---------------------------------------------------------------------------

function Invoke-ProfileRestore([string]$path) {
    $r = New-Object PSObject -Property @{
        Path = $path; Folder = (Get-SteamIdLabel $path); Ok = $true; Error = $null
        Renamed = (New-Object System.Collections.Generic.List[string])
        Removed = (New-Object System.Collections.Generic.List[string])
        RetiredFound = (New-Object System.Collections.Generic.List[string])
        UnresolvedFound = (New-Object System.Collections.Generic.List[string])
        Backup = $null; Written = $false
    }
    try {
        # --- read -----------------------------------------------------------
        $origBytes = [System.IO.File]::ReadAllBytes($path)
        $text = [System.IO.File]::ReadAllText($path)
        $hasBom = ($origBytes.Length -ge 3 -and $origBytes[0] -eq 0xEF -and $origBytes[1] -eq 0xBB -and $origBytes[2] -eq 0xBF)
        $writeEnc = New-Object System.Text.UTF8Encoding $hasBom
        # The file must survive a decode/encode round trip exactly, otherwise a
        # rewrite could change bytes we did not mean to touch.
        $rt = $Utf8Strict.GetBytes($text)
        if ($hasBom) { $rt = [byte[]](@(0xEF, 0xBB, 0xBF) + $rt) }
        if ((ConvertTo-B64 $rt) -cne (ConvertTo-B64 $origBytes)) {
            throw 'the file is not plain UTF-8 text that can be rewritten byte-for-byte; not touching it'
        }

        try { $origObj = ConvertFrom-Json -InputObject $text }
        catch { throw "Profile.json is not valid JSON: $($_.Exception.Message)" }
        if ($null -eq $origObj -or -not ($origObj -is [System.Management.Automation.PSCustomObject])) {
            throw 'Profile.json top level is not a JSON object'
        }
        $origTalents = Get-TalentList $origObj

        $span = Find-TalentsArray $text
        $count = $span.Starts.Count
        if ($count -ne $origTalents.Count) {
            throw "Talents text scan found $count entries but the JSON parser found $($origTalents.Count)"
        }

        # --- plan -----------------------------------------------------------
        $present = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($e in $origTalents) {
            $nm = Get-RowName $e
            if ($null -ne $nm) { [void]$present.Add($nm) }
        }
        foreach ($e in $origTalents) {
            $nm = Get-RowName $e
            if ($null -eq $nm) { continue }
            if ($Retired.Contains($nm)) { $r.RetiredFound.Add($nm) }
            if ($Unresolved.ContainsKey($nm)) { $r.UnresolvedFound.Add($nm) }
        }

        $action = New-Object 'object[]' $count      # $null | 'rename' | 'remove'
        $newName = New-Object 'string[]' $count
        $restoredNames = New-Object System.Collections.Generic.List[string]
        for ($k = 0; $k -lt $count; $k++) {
            $parsedName = Get-RowName $origTalents[$k]
            if ($null -eq $parsedName -or -not $Mapping.ContainsKey($parsedName)) { continue }
            $elText = $text.Substring($span.Starts[$k], $span.Ends[$k] - $span.Starts[$k])
            $g = Get-EntryNameGroup $elText
            if ($null -eq $g -or $g.Value -cne $parsedName) {
                throw "entry #$($k + 1) ('$parsedName') is not in the expected {""RowName"": ..., ""Rank"": ...} form; not touching this file"
            }
            $target = $Mapping[$parsedName]
            if ($present.Contains($target)) {
                $action[$k] = 'remove'
                $r.Removed.Add("$parsedName (already have $target)")
            }
            else {
                $action[$k] = 'rename'
                $newName[$k] = $target
                [void]$present.Add($target)
                $restoredNames.Add($target)
                $r.Renamed.Add("$parsedName -> $target")
            }
        }

        if ($r.Renamed.Count -eq 0 -and $r.Removed.Count -eq 0) { return $r }

        # --- build new text (splice inside the Talents array only) ----------
        $sb = New-Object System.Text.StringBuilder
        [void]$sb.Append($text, 0, $span.Open + 1)
        if ($count -gt 0) {
            [void]$sb.Append($text, $span.Open + 1, $span.Starts[0] - ($span.Open + 1))
        }
        $prevKept = -1
        for ($k = 0; $k -lt $count; $k++) {
            if ($action[$k] -eq 'remove') { continue }
            if ($prevKept -ge 0) {
                # Separator that originally followed the previous kept entry
                # (its comma and line break), so one comma goes with each removal.
                [void]$sb.Append($text, $span.Ends[$prevKept], $span.Starts[$prevKept + 1] - $span.Ends[$prevKept])
            }
            $elText = $text.Substring($span.Starts[$k], $span.Ends[$k] - $span.Starts[$k])
            if ($action[$k] -eq 'rename') {
                $g = Get-EntryNameGroup $elText
                $elText = $elText.Substring(0, $g.Index) + $newName[$k] + $elText.Substring($g.Index + $g.Length)
            }
            [void]$sb.Append($elText)
            $prevKept = $k
        }
        if ($count -gt 0) {
            [void]$sb.Append($text, $span.Ends[$count - 1], $span.Close - $span.Ends[$count - 1])
        }
        [void]$sb.Append($text, $span.Close, $text.Length - $span.Close)
        $newText = $sb.ToString()

        # --- validate -------------------------------------------------------
        $head = $text.Substring(0, $span.Open + 1)
        $tail = $text.Substring($span.Close)
        if (-not $newText.StartsWith($head, [System.StringComparison]::Ordinal) -or
            -not $newText.EndsWith($tail, [System.StringComparison]::Ordinal)) {
            throw 'validation failed: text outside the Talents array changed'
        }
        try { $newObj = ConvertFrom-Json -InputObject $newText }
        catch { throw "validation failed: edited text is not valid JSON: $($_.Exception.Message)" }
        $newSpan = Find-TalentsArray $newText
        if ($newSpan.Open -ne $span.Open) { throw 'validation failed: Talents array moved' }

        $on = @($origObj.PSObject.Properties | ForEach-Object { $_.Name })
        $nn = @($newObj.PSObject.Properties | ForEach-Object { $_.Name })
        if (($on -join "`n") -cne ($nn -join "`n")) { throw 'validation failed: top-level keys differ' }
        foreach ($name in $on) {
            if ($name -ceq 'Talents') { continue }
            $a = ConvertTo-Json -InputObject $origObj.PSObject.Properties[$name].Value -Depth 20 -Compress
            $b = ConvertTo-Json -InputObject $newObj.PSObject.Properties[$name].Value -Depth 20 -Compress
            if ($a -cne $b) { throw "validation failed: top-level '$name' changed" }
        }

        $newTalents = Get-TalentList $newObj
        $expectedCount = $origTalents.Count - $r.Removed.Count
        if ($newTalents.Count -ne $expectedCount) {
            throw "validation failed: expected $expectedCount Talents entries, found $($newTalents.Count)"
        }
        $ni = 0
        for ($k = 0; $k -lt $count; $k++) {
            if ($action[$k] -eq 'remove') { continue }
            $o = $origTalents[$k]
            $x = $newTalents[$ni]
            if ($action[$k] -eq 'rename') {
                if ((Get-RowName $x) -cne $newName[$k] -or (Get-EntrySig $o $newName[$k]) -cne (Get-EntrySig $x $null)) {
                    throw "validation failed: restored entry #$($ni + 1) is not '$($newName[$k])' with the original Rank"
                }
            }
            elseif ((Get-EntrySig $o $null) -cne (Get-EntrySig $x $null)) {
                throw "validation failed: untouched entry #$($k + 1) changed or moved"
            }
            $ni++
        }
        $newCounts = New-Object 'System.Collections.Generic.Dictionary[string,int]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($x in $newTalents) {
            $nm = Get-RowName $x
            if ($null -eq $nm) { continue }
            if ($Mapping.ContainsKey($nm)) { throw "validation failed: old name '$nm' is still present" }
            if ($newCounts.ContainsKey($nm)) { $newCounts[$nm]++ } else { $newCounts[$nm] = 1 }
        }
        foreach ($nm in $restoredNames) {
            if (-not $newCounts.ContainsKey($nm) -or $newCounts[$nm] -ne 1) {
                throw "validation failed: restored name '$nm' does not appear exactly once"
            }
        }
        foreach ($item in $r.Removed) {
            $target = ($item -replace '^.*\(already have (.+)\)$', '$1')
            if (-not $newCounts.ContainsKey($target) -or $newCounts[$target] -ne 1) {
                throw "validation failed: '$target' does not appear exactly once"
            }
        }

        if ($DryRun) { return $r }

        # --- backup + write -------------------------------------------------
        $newBytes = $writeEnc.GetBytes($newText)
        if ($hasBom) { $newBytes = [byte[]](@(0xEF, 0xBB, 0xBF) + $newBytes) }

        $nowBytes = [System.IO.File]::ReadAllBytes($path)
        if ((ConvertTo-B64 $nowBytes) -cne (ConvertTo-B64 $origBytes)) {
            throw 'Profile.json changed while the tool was running; nothing written'
        }

        $stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
        $bak = "$path.kitrestore_$stamp.bak"
        $suffix = 2
        while (Test-Path -LiteralPath $bak) {
            $bak = "$path.kitrestore_${stamp}_$suffix.bak"
            $suffix++
        }
        try {
            [System.IO.File]::Copy($path, $bak, $false)
            $bakBytes = [System.IO.File]::ReadAllBytes($bak)
            if ((ConvertTo-B64 $bakBytes) -cne (ConvertTo-B64 $origBytes)) { throw 'backup copy does not match the original' }
        }
        catch { throw "could not create backup '$bak': $($_.Exception.Message); nothing written" }
        $r.Backup = $bak

        try {
            [System.IO.File]::WriteAllText($path, $newText, $writeEnc)
        }
        catch { throw "writing Profile.json failed: $($_.Exception.Message). The original is in '$bak'" }
        $written = [System.IO.File]::ReadAllBytes($path)
        if ((ConvertTo-B64 $written) -cne (ConvertTo-B64 $newBytes)) {
            throw "Profile.json did not read back as written. The original is in '$bak'"
        }
        $r.Written = $true
    }
    catch {
        $r.Ok = $false
        $r.Error = $_.Exception.Message
    }
    return $r
}

# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

function Get-CleanPath([string]$p) {
    # A quoted path ending in \" arrives with a stray quote from the .bat.
    return $p.Trim().Trim('"').Trim()
}

Write-Host 'Restore Kit Research - Agents Individual Item Kits. Made by AgentKush.'
if ($DryRun) { Write-Host 'DRY RUN: nothing will be written and no backup will be made.' -ForegroundColor Yellow }
Write-Host ''

$running = @()
if (-not $SkipGameCheck) {
    $running = @(Get-Process -Name $GameProcessNames -ErrorAction SilentlyContinue)
    if ($running.Count -gt 0) {
        $names = ($running | ForEach-Object { $_.ProcessName + '.exe' } | Sort-Object -Unique) -join ', '
        if (-not $DryRun) {
            Write-Host "Icarus is running ($names). Close the game completely, then run this again." -ForegroundColor Red
            Write-Host 'Nothing was changed.'
            exit 2
        }
        Write-Host "Warning: Icarus is running ($names). This dry run only reads files, but close the game before the real run." -ForegroundColor Yellow
        Write-Host ''
    }
}

$failed = $false
$targets = New-Object System.Collections.Generic.List[string]

if ($ProfilePath) {
    foreach ($p in $ProfilePath) {
        $p = Get-CleanPath $p
        if (Test-Path -LiteralPath $p -PathType Leaf) {
            $targets.Add((Resolve-Path -LiteralPath $p).ProviderPath)
        }
        else {
            Write-Host "Profile file not found: $p" -ForegroundColor Red
            $failed = $true
        }
    }
}
$folders = @()
if ($PlayerDataPath) { $folders = @($PlayerDataPath | ForEach-Object { Get-CleanPath $_ }) }
elseif (-not $ProfilePath) {
    if (-not $env:LOCALAPPDATA) {
        Write-Host 'LOCALAPPDATA is not set; use -PlayerDataPath or -ProfilePath.' -ForegroundColor Red
        exit 1
    }
    $folders = @(Join-Path $env:LOCALAPPDATA 'Icarus\Saved\PlayerData')
}
foreach ($f in $folders) {
    if (-not (Test-Path -LiteralPath $f -PathType Container)) {
        Write-Host "Folder not found: $f" -ForegroundColor Red
        $failed = $true
        continue
    }
    $direct = Join-Path $f 'Profile.json'
    if (Test-Path -LiteralPath $direct -PathType Leaf) {
        $targets.Add((Resolve-Path -LiteralPath $direct).ProviderPath)
        continue
    }
    $found = 0
    foreach ($sub in @(Get-ChildItem -LiteralPath $f -Directory | Sort-Object Name)) {
        $cand = Join-Path $sub.FullName 'Profile.json'
        if (Test-Path -LiteralPath $cand -PathType Leaf) {
            $targets.Add($cand)
            $found++
        }
    }
    if ($found -eq 0) {
        Write-Host "No Profile.json found in $f or its SteamID folders." -ForegroundColor Red
        $failed = $true
    }
}

$seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
foreach ($t in $targets) {
    if (-not $seen.Add($t)) { continue }
    $r = Invoke-ProfileRestore $t

    Write-Host "SteamID folder: $($r.Folder)" -ForegroundColor Cyan
    Write-Host "  File: $($r.Path)"
    if (-not $r.Ok) {
        Write-Host "  FAILED: $($r.Error)" -ForegroundColor Red
        if ($r.Backup) { Write-Host "  Backup: $($r.Backup)" }
        else { Write-Host '  Nothing was written for this profile.' }
        $failed = $true
        Write-Host ''
        continue
    }

    $verb = 'restored'
    if ($DryRun) { $verb = 'would be restored' }
    Write-Host "  $($r.Renamed.Count) kits $verb"
    foreach ($x in $r.Renamed) { Write-Host "    $x" }
    $verb = 'removed'
    if ($DryRun) { $verb = 'would be removed' }
    Write-Host "  $($r.Removed.Count) duplicate old entries $verb"
    foreach ($x in $r.Removed) { Write-Host "    $x" }

    if ($r.RetiredFound.Count -eq 0 -and $r.UnresolvedFound.Count -eq 0) {
        Write-Host '  Retired kits found: none'
    }
    else {
        Write-Host "  Retired kits found: $($r.RetiredFound.Count + $r.UnresolvedFound.Count) (left unchanged, cannot be restored)"
        foreach ($x in $r.RetiredFound) { Write-Host "    $x" }
        foreach ($x in $r.UnresolvedFound) {
            Write-Host "    $x (the current kit is not proven to give the same item)"
            Write-Host "      $($Unresolved[$x])" -ForegroundColor DarkGray
        }
    }

    if ($r.Renamed.Count -eq 0 -and $r.Removed.Count -eq 0) {
        Write-Host '  Nothing to change. File not written, no backup made.' -ForegroundColor Green
    }
    elseif ($DryRun) {
        Write-Host '  Backup: none (dry run, nothing written)'
    }
    else {
        Write-Host "  Backup: $($r.Backup)"
        Write-Host '  Profile.json updated.' -ForegroundColor Green
    }
    Write-Host ''
}

if ($seen.Count -eq 0 -and -not $failed) {
    Write-Host 'No Profile.json files to process.' -ForegroundColor Red
    $failed = $true
}

Write-Host 'Close the game before running this tool. Steam Cloud will upload the updated file next time the game syncs.'
if ($failed) { exit 1 }
exit 0
